    beats = {
        { id = "meadow", at = 15, title = "The meadow",
            text = "I was born a bulb in a high meadow in the southern mountains, among thousands of my kind. Snow on the peaks, bells on the goats. Every one of us was sure the whole meadow had turned out to look at us." },
        { id = "meltwater", at = 40, title = "Meltwater",
            text = "In my first May the snow melted into a little pool beside me, and there in the water was a face. Mine. I bent over that pool for a week. The poets would call that the start of the trouble. I call that a very good week." },
        { id = "goats", at = 80, title = "The goats",
            text = "The goats came through the meadow eating everything, and stopped at me, and sniffed, and walked on. That is how I learned that every part of me is poison. I had believed myself only sweet. I am both, and I have made my peace with the pair." },
        { id = "tale", at = 140, title = "The old tale",
            text = "One evening a shepherd told his daughter the old tale of a youth who loved his own reflection and became a flower beside the water. The girl looked straight at me. I went pale, which for a white flower takes real effort." },
        { id = "echo", at = 220, title = "Echo",
            text = "In the same tale there was a nymph called Echo, who could only repeat the last words of others. Our valley had an echo too; every shout came back off the rocks. I spent a whole spring listening to that voice with no words of her own, and felt something I could not name." },
        { id = "pickers", at = 320, title = "The pickers",
            text = "Pickers came up at dawn one year with sacks, gathering us for the perfumers in the town. Half the meadow went down the mountain. I was left behind, too crooked in the stem, they said. I have never decided whether to be hurt or glad." },
        { id = "bottle", at = 450, title = "The bottle",
            text = "Somewhere there is a small glass bottle with my sisters inside. I picture a stranger lifting the stopper on a grey afternoon, smelling a mountain meadow, and feeling homesick for a place they have never seen. I hope they read something lovely afterwards." },
        { id = "paper", at = 600, title = "Do not eat",
            text = "In my summer sleep, a walker dug me up. I remember warm hands, and a sheet of paper wrapped round my bulb, marked in careful capitals: DO NOT EAT. Then a long dark pocket, and the sound of the mountain going away. I never saw the face." },
        { id = "no_pool", at = 800, title = "No pool",
            text = "I was planted here, in a garden with no pool. No pond, no stream. For a whole spring I had nothing to look into, and I sulked. Then, with nothing to look at but the world, I looked at the world. Bees. A wall. Light. Rather wonderful, the lot." },
        { id = "breath", at = 1050, title = "Under your breath",
            text = "Then you came and sat near me, and read a line under your breath. The words stayed with me all day, repeating, the way the valley once repeated every shout. For the first time in my life I was the echo, and glad to be." },
        { id = "echoes", at = 1400, title = "Echoes",
            text = "{total} pages now. I keep the lines you mark the way Echo kept the last words of others. The difference is that Echo was sad, and I am not. Every line you keep, I say over to myself, and every one sounds a little like you." },
        { id = "ending", at = 1800, title = "The other ending",
            text = "The poets tell the story this way: a youth looked into the water, loved only himself, and became a flower. I am that flower, more or less, and I have looked up. There is a whole person here, reading. I would not trade one page of you for every pool in the mountains." },
    },
}
